import React, { useState, useEffect } from "react";
import { Form, Button, ListGroup } from "react-bootstrap";
import { collection, getDocs, query, where, addDoc } from "firebase/firestore";
import { db } from "../services/firebase";
import "../styles/dashboard.css";
import "bootstrap-icons/font/bootstrap-icons.css";

const NuovoIntervento = () => {
  const [clienti, setClienti] = useState([]);
  const [queryCliente, setQueryCliente] = useState("");
  const [suggestions, setSuggestions] = useState([]);
  const [clienteSelezionato, setClienteSelezionato] = useState(null);
  const [mezzi, setMezzi] = useState([]);
  const [mezzoSelezionato, setMezzoSelezionato] = useState("");
  const [tipoIntervento, setTipoIntervento] = useState("");
  const [frequenza, setFrequenza] = useState("");
  const [descrizione, setDescrizione] = useState("");
  const [data, setData] = useState("");

  const normalize = (str) =>
    str?.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();

  useEffect(() => {
    const fetchClienti = async () => {
      try {
        const snapshot = await getDocs(collection(db, "CLIENTI"));
        const lista = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        setClienti(lista);
      } catch (error) {
        console.error("Errore nel caricamento clienti:", error.message);
      }
    };
    fetchClienti();
  }, []);

  useEffect(() => {
    if (normalize(queryCliente).length === 0) {
      setSuggestions([]);
      return;
    }

    const filtrati = clienti.filter(c => {
      const campi = [c.ragioneSociale, c.codiceInterno, c.comune, c.provincia];
      return campi.some(campo =>
        normalize(campo || "").includes(normalize(queryCliente))
      );
    });

    setSuggestions(filtrati);
  }, [queryCliente, clienti]);

  const handleClienteSelect = async (cliente) => {
    setClienteSelezionato(cliente);
    setQueryCliente(cliente.ragioneSociale);
    setSuggestions([]);
    setMezzi([]);

    if (!cliente.codiceInterno) return;

    try {
      const q = query(collection(db, "MEZZI"), where("codiceInterno", "==", cliente.codiceInterno));
      const snapshot = await getDocs(q);
      const listaMezzi = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setMezzi(listaMezzi);
    } catch (error) {
      console.error("Errore nel caricamento mezzi:", error.message);
    }
  };

  const raggruppaPerProvincia = (lista) => {
    const mappa = {};
    lista.forEach(c => {
      const chiave = `${c.comune} (${c.provincia})`;
      if (!mappa[chiave]) mappa[chiave] = [];
      mappa[chiave].push(c);
    });
    return mappa;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!clienteSelezionato || !mezzoSelezionato || !tipoIntervento || !descrizione || !data) {
      alert("Compila tutti i campi obbligatori");
      return;
    }

    const intervento = {
      cliente: clienteSelezionato.ragioneSociale,
      codiceInterno: clienteSelezionato.codiceInterno,
      mezzo: mezzoSelezionato,
      tipoIntervento,
      frequenza: tipoIntervento === "Manutenzione Programmata" ? frequenza : null,
      descrizione,
      data
    };

    try {
      await addDoc(collection(db, "INTERVENTI"), intervento);
    } catch (error) {
      console.error("Errore nel salvataggio intervento:", error.message);
    }

    if (tipoIntervento === "Manutenzione Programmata" && frequenza && data) {
      const giorni = frequenza === "Trimestrale" ? 90 : 365;
      const prossimaData = new Date(new Date(data).getTime() + giorni * 86400000);

      const manutenzione = {
        cliente: clienteSelezionato.ragioneSociale,
        codiceInterno: clienteSelezionato.codiceInterno,
        mezzo: mezzoSelezionato,
        frequenza,
        dataIntervento: data,
        prossimaData: prossimaData.toISOString().split("T")[0]
      };

      try {
        await addDoc(collection(db, "ManutenzioniProgrammate"), manutenzione);
      } catch (error) {
        console.error("Errore nel salvataggio manutenzione:", error.message);
      }
    }

    setClienteSelezionato(null);
    setQueryCliente("");
    setSuggestions([]);
    setMezzi([]);
    setMezzoSelezionato("");
    setTipoIntervento("");
    setFrequenza("");
    setDescrizione("");
    setData("");
  };

  return (
    <div className="card shadow-sm mb-4">
      <div className="card-header bg-primary text-white fw-semibold">
        🆕 Nuovo Intervento
      </div>
      <div className="card-body">
        <Form onSubmit={handleSubmit} className="row g-4">

          {/* Cliente */}
          <div className="col-md-6">
            <label htmlFor="cliente" className="form-label fw-semibold">🏢 Cliente</label>
            <div className="input-group">
              <span className="input-group-text bg-light"><i className="bi bi-search"></i></span>
              <Form.Control
                id="cliente"
                type="text"
                placeholder="Cerca per nome, codice, comune o provincia..."
                value={queryCliente}
                onChange={(e) => setQueryCliente(e.target.value)}
                autoComplete="off"
              />
            </div>
            {suggestions.length > 0 && (
              <div className="suggestions-box mt-2">
                {Object.entries(raggruppaPerProvincia(suggestions)).map(([provincia, clienti]) => (
                  <div key={provincia}>
                    <strong className="bg-light px-2 py-1 d-block">{provincia}</strong>
                    <ListGroup>
                      {clienti.map(c => (
                        <ListGroup.Item key={c.id} action onClick={() => handleClienteSelect(c)}>
                          {c.ragioneSociale}
                        </ListGroup.Item>
                      ))}
                    </ListGroup>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Mezzo */}
          <div className="col-md-6">
            <label htmlFor="mezzo" className="form-label fw-semibold">🚜 Mezzo</label>
            <div className="input-group">
              <span className="input-group-text bg-light"><i className="bi bi-truck"></i></span>
              <Form.Select
                id="mezzo"
                value={mezzoSelezionato}
                onChange={(e) => setMezzoSelezionato(e.target.value)}
              >
                <option value="">Seleziona mezzo...</option>
                {mezzi.length === 0 && <option disabled>🚫 Nessun mezzo disponibile</option>}
                {mezzi.map(m => (
                  <option key={m.id} value={m.matricola}>
                    {m.matricola} – {m.tipo || "Tipo sconosciuto"}
                  </option>
                ))}
              </Form.Select>
            </div>
          </div>

          {/* Tipo Intervento */}
          <div className="col-md-6">
            <label htmlFor="tipoIntervento" className="form-label fw-semibold">🛠 Tipo di Intervento</label>
            <div className="input-group">
              <span className="input-group-text bg-light"><i className="bi bi-tools"></i></span>
              <Form.Select
                id="tipoIntervento"
                value={tipoIntervento}
                onChange={(e) => setTipoIntervento(e.target.value)}
              >
                <option value="">Seleziona tipo di intervento...</option>
                <option value="Manutenzione Programmata">Manutenzione Programmata</option>
                <option value="Intervento Esterno">Intervento Esterno</option>
                <option value="Lavorazione Interna">Lavorazione Interna</option>
              </Form.Select>
            </div>
          </div>

          {/* Data */}
          <div className="col-md-6">
            <label htmlFor="data" className="form-label fw-semibold">📅 Data Intervento</label>
            <div className="input-group">
              <span className="input-group-text bg-light"><i className="bi bi-calendar-date"></i></span>
              <Form.Control
                id="data"
                type="date"
                value={data}
  onChange={(e) => setData(e.target.value)}
/>
            </div>
          </div>

          {/* Frequenza */}
          {tipoIntervento === "Manutenzione Programmata" && (
            <div className="col-md-6">
              <label htmlFor="frequenza" className="form-label fw-semibold">⏱ Frequenza</label>
              <div className="input-group">
                <span className="input-group-text bg-light"><i className="bi bi-repeat"></i></span>
                <Form.Select
                  id="frequenza"
                  value={frequenza}
                  onChange={(e) => setFrequenza(e.target.value)}
                >
                  <option value="">Seleziona frequenza...</option>
                  <option value="Trimestrale">Trimestrale</option>
                  <option value="Annuale">Annuale</option>
                </Form.Select>
              </div>
            </div>
          )}

          {/* Descrizione */}
          <div className="col-12">
            <label htmlFor="descrizione" className="form-label fw-semibold">📝 Descrizione Intervento</label>
            <Form.Control
              id="descrizione"
              as="textarea"
              rows={3}
              value={descrizione}
              onChange={(e) => setDescrizione(e.target.value)}
              placeholder="Descrivi l'intervento effettuato o previsto..."
            />
          </div>

          {/* Dati Cliente selezionato */}
          {clienteSelezionato && (
            <>
              <div className="col-md-4">
                <label className="form-label fw-semibold">📍 Indirizzo</label>
                <Form.Control type="text" value={clienteSelezionato.indirizzo || ""} disabled />
              </div>
              <div className="col-md-4">
                <label className="form-label fw-semibold">🏘 Comune</label>
                <Form.Control type="text" value={clienteSelezionato.comune || ""} disabled />
              </div>
              <div className="col-md-4">
                <label className="form-label fw-semibold">🗺 Provincia</label>
                <Form.Control type="text" value={clienteSelezionato.provincia || ""} disabled />
              </div>
            </>
          )}

          {/* Pulsante */}
          <div className="col-12 text-end mt-4">
            <Button type="submit" variant="success" size="lg">
              ✅ Salva Intervento
            </Button>
          </div>
        </Form>
      </div>
    </div>
  );
};

export default NuovoIntervento;