// 🔗 Importa i moduli Firebase necessari
import { initializeApp } from "firebase/app";
import { getFirestore, connectFirestoreEmulator } from "firebase/firestore";
import { getAuth } from "firebase/auth";
import { getStorage } from "firebase/storage";

// ✅ Configurazione del progetto Firebase tramite variabili ambiente
const firebaseConfig = {
  apiKey: process.env.REACT_APP_FIREBASE_API_KEY,
  authDomain: process.env.REACT_APP_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.REACT_APP_FIREBASE_PROJECT_ID,
  storageBucket: process.env.REACT_APP_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.REACT_APP_FIREBASE_APP_ID
};

// 🧪 Debug: stampa la chiave API se in sviluppo
if (process.env.NODE_ENV === "development") {
  console.log("🔑 API Key:", process.env.REACT_APP_FIREBASE_API_KEY);
}

// 🚀 Inizializza Firebase
const app = initializeApp(firebaseConfig);

// 🔌 Inizializza i servizi
const db = getFirestore(app);
const auth = getAuth(app);
const storage = getStorage(app);

// 🧪 Collegamento all’emulatore Firestore se in locale
if (window.location.hostname === "localhost") {
  console.log("🧪 Connessione all'emulatore Firestore...");
  connectFirestoreEmulator(db, "127.0.0.1", 8080);
}

export { db, auth, storage };