import React, { useState } from "react";
import "./dashboard.css";

const CambioPassword = () => {
  const [vecchia, setVecchia] = useState("");
  const [nuova, setNuova] = useState("");
  const [conferma, setConferma] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!vecchia || !nuova || nuova !== conferma) {
      alert("⚠️ Controlla i campi");
      return;
    }
    console.log("🔐 Password aggiornata");
    setVecchia(""); setNuova(""); setConferma("");
  };

  return (
    <div className="card">
      <div className="card-header">🔐 Cambio Password</div>
      <div className="card-body">
        <form className="form-grid" onSubmit={handleSubmit}>
          <div>
            <label>Vecchia Password</label>
            <input type="password" value={vecchia} onChange={(e) => setVecchia(e.target.value)} />
          </div>
          <div>
            <label>Nuova Password</label>
            <input type="password" value={nuova} onChange={(e) => setNuova(e.target.value)} />
          </div>
          <div>
            <label>Conferma Nuova Password</label>
            <input type="password" value={conferma} onChange={(e) => setConferma(e.target.value)} />
          </div>
          <div style={{ gridColumn: "span 2", textAlign: "right" }}>
            <button type="submit" className="btn-success">💾 Aggiorna</button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default CambioPassword;