import React from "react";
import Form from "react-bootstrap/Form";
import Row from "react-bootstrap/Row";
import Col from "react-bootstrap/Col";

const tipiIntervento = [
  "Manutenzione Programmata",
  "Intervento Esterno",
  "Lavorazione Interna"
];

const mesi = [
  "Gennaio", "Febbraio", "Marzo", "Aprile", "Maggio", "Giugno",
  "Luglio", "Agosto", "Settembre", "Ottobre", "Novembre", "Dicembre"
];

const FiltroInterventi = ({ filtri, setFiltri, clienti = [] }) => {
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFiltri(prev => ({ ...prev, [name]: value }));
  };

  return (
    <Form className="mb-4">
      <h5 className="mb-3">🔍 Filtra Interventi</h5>
      <Row className="gy-3">
        <Col md={4}>
          <Form.Group>
            <Form.Label>Tipo di Intervento</Form.Label>
            <Form.Select
              name="tipoIntervento"
              value={filtri.tipoIntervento}
              onChange={handleChange}
            >
              <option value="">Tutti</option>
              {tipiIntervento.map(tipo => (
                <option key={tipo} value={tipo}>{tipo}</option>
              ))}
            </Form.Select>
          </Form.Group>
        </Col>

        <Col md={4}>
          <Form.Group>
            <Form.Label>Cliente</Form.Label>
            <Form.Select
              name="cliente"
              value={filtri.cliente}
              onChange={handleChange}
            >
              <option value="">Tutti</option>
              {clienti.map(c => (
                <option key={c} value={c}>{c}</option>
              ))}
            </Form.Select>
          </Form.Group>
        </Col>

        <Col md={4}>
          <Form.Group>
            <Form.Label>Mese</Form.Label>
            <Form.Select
              name="mese"
              value={filtri.mese}
              onChange={handleChange}
            >
              <option value="">Tutti</option>
              {mesi.map((mese, index) => (
                <option key={mese} value={index + 1}>{mese}</option>
              ))}
            </Form.Select>
          </Form.Group>
        </Col>
      </Row>
    </Form>
  );
};

export default FiltroInterventi;