import React, { useEffect, useState } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../services/firebase";
import "./dashboard.css";

const CalendarioManutenzioni = () => {
  const [manutenzioni, setManutenzioni] = useState([]);

  useEffect(() => {
    const fetchManutenzioni = async () => {
      try {
        const snapshot = await getDocs(collection(db, "ManutenzioniProgrammate"));
        const lista = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        setManutenzioni(lista);
        console.log("📅 Manutenzioni caricate:", lista.length);
      } catch (error) {
        console.error("❌ Errore nel caricamento:", error.message);
      }
    };

    fetchManutenzioni();
  }, []);

  return (
    <div className="card">
      <div className="card-header bg-primary text-white">
        📅 Calendario Manutenzioni Programmate
      </div>
      <div className="card-body">
        {manutenzioni.length === 0 ? (
          <p>Nessuna manutenzione programmata disponibile.</p>
        ) : (
          <table className="table">
            <thead>
              <tr>
                <th>Cliente</th>
                <th>Mezzo</th>
                <th>Frequenza</th>
                <th>Data Intervento</th>
                <th>Prossima Manutenzione</th>
              </tr>
            </thead>
            <tbody>
              {manutenzioni.map(m => (
                <tr key={m.id}>
                  <td>{m.cliente || "—"}</td>
                  <td>{m.mezzo || "—"}</td>
                  <td>{m.frequenza || "—"}</td>
                  <td>{m.dataIntervento || "—"}</td>
                  <td>{m.prossimaData || "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default CalendarioManutenzioni;