import React, { useState } from "react";
import PaginaLayout from "../components/PaginaLayout";
import NuovoIntervento from "../components/NuovoIntervento";
import MappaClienti from "../components/MappaClienti";
import CreaUtente from "../components/CreaUtente";
import ListaUtenti from "../components/ListaUtenti";
import "./dashboard.css";

const DashboardAdmin = () => {
  const [clienteSelezionato, setClienteSelezionato] = useState(null);
  const [coordinate, setCoordinate] = useState(null);

  const handleSelect = (cliente) => {
    if (!cliente) {
      setClienteSelezionato(null);
      setCoordinate(null);
      return;
    }

    setClienteSelezionato(cliente);

    const lat = parseFloat(cliente.lat || cliente.posizione?.lat);
    const lng = parseFloat(cliente.lng || cliente.posizione?.lng);

    if (!isNaN(lat) && !isNaN(lng)) {
      setCoordinate({ lat, lng });
    } else {
      console.warn("⚠️ Coordinate non valide");
      setCoordinate(null);
    }
  };

  return (
    <PaginaLayout titolo="📊 Dashboard Amministratore">
      <p className="intro-text">
        Benvenuto Massimo! Qui puoi monitorare l’attività generale, gestire utenti e visualizzare interventi.
      </p>

      <div className="card">
        <div className="card-header">🛠️ Crea Nuovo Intervento</div>
        <div className="card-body">
          <NuovoIntervento onSelectCliente={handleSelect} />
        </div>
      </div>

      {coordinate && clienteSelezionato && (
        <div className="card">
          <div className="card-header">📍 Posizione Cliente</div>
          <div className="card-body">
            <MappaClienti
              coordinate={coordinate}
              nome={clienteSelezionato.ragioneSociale || clienteSelezionato.Cliente || "Cliente"}
            />
          </div>
        </div>
      )}

      <div className="card">
        <div className="card-header">➕ Crea Nuovo Utente</div>
        <div className="card-body">
          <CreaUtente />
        </div>
      </div>

      <div className="card">
        <div className="card-header">📋 Elenco Utenti Registrati</div>
        <div className="card-body">
          <ListaUtenti />
        </div>
      </div>
    </PaginaLayout>
  );
};

export default DashboardAdmin;