import React from "react";
import "./dashboard.css";

const utentiFinti = [
  { id: 1, nome: "Veronica Sotillo", email: "veronica@azienda.it", ruolo: "Admin" },
  { id: 2, nome: "Mario Rossi", email: "mario@azienda.it", ruolo: "Tecnico" },
  { id: 3, nome: "Anna Verdi", email: "anna@azienda.it", ruolo: "Cliente" },
];

const ListaUtenti = () => {
  return (
    <table className="table">
      <thead>
        <tr>
          <th>Nome</th>
          <th>Email</th>
          <th>Ruolo</th>
          <th>Azioni</th>
        </tr>
      </thead>
      <tbody>
        {utentiFinti.map(u => (
          <tr key={u.id}>
            <td>{u.nome}</td>
            <td>{u.email}</td>
            <td>{u.ruolo}</td>
            <td>
              <button className="btn-warning">✏️ Modifica</button>{" "}
              <button className="btn-danger">🗑️ Elimina</button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
};

export default ListaUtenti;