import React, { useContext } from "react";
import { Navigate } from "react-router-dom";
import { AuthContext } from "../contexts/AuthContext";

function ProtectedRoute({ children, ruoloRichiesto }) {
  const { user, ruolo, loading } = useContext(AuthContext);

  if (loading) {
    return <p className="text-muted p-3">🔄 Verifica accesso...</p>;
  }

  if (!user) {
    return <Navigate to="/login" />;
  }

  if (ruoloRichiesto && ruolo !== ruoloRichiesto) {
    return <h5 className="text-danger">⛔ Accesso negato: ruolo non autorizzato</h5>;
  }

  return children;
}

export default ProtectedRoute;