import React, { useState } from "react";
import { NavLink, useNavigate } from "react-router-dom";
import { useAuth } from "../contexts/AuthContext";
import { signOut } from "firebase/auth";
import { auth } from "../services/firebase";
import {
  FaBars, FaHome, FaUsers, FaTools, FaChartBar,
  FaMapMarkedAlt, FaUserCog, FaKey, FaCalendarAlt, FaSignOutAlt
} from "react-icons/fa";
import "./Sidebar.css";

const SidebarMobile = () => {
  const { ruolo } = useAuth();
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);

  const toggleMenu = () => setOpen(!open);

  const handleLogout = async () => {
    await signOut(auth);
    navigate("/login");
  };

  const menuConfig = {
    admin: [
      { label: "Dashboard", path: "/", icon: <FaHome /> },
      { label: "Clienti", path: "/clienti", icon: <FaUsers /> },
      { label: "Mezzi", path: "/mezzi", icon: <FaTools /> },
      { label: "Report", path: "/report", icon: <FaChartBar /> },
      { label: "Utenti", path: "/utenti", icon: <FaUserCog /> },
      { label: "Manutenzioni", path: "/manutenzioni-programmate/calendario", icon: <FaCalendarAlt /> },
      { label: "Profilo", path: "/profilo", icon: <FaUserCog /> },
      { label: "Password", path: "/recupero", icon: <FaKey /> }
    ],
    tecnico: [
      { label: "Dashboard", path: "/", icon: <FaHome /> },
      { label: "Report", path: "/report", icon: <FaChartBar /> },
      { label: "Mezzi", path: "/mezzi", icon: <FaTools /> },
      { label: "Mappa", path: "/mappa-clienti", icon: <FaMapMarkedAlt /> },
      { label: "Manutenzioni", path: "/manutenzioni-programmate/calendario", icon: <FaCalendarAlt /> },
      { label: "Profilo", path: "/profilo", icon: <FaUserCog /> },
      { label: "Password", path: "/recupero", icon: <FaKey /> }
    ]
  };

  const menu = menuConfig[ruolo] || [];

  return (
    <>
      <div className="hamburger-icon" onClick={toggleMenu} aria-label="Apri menu mobile">
        <FaBars size={20} />
      </div>

      <div className={`sidebar-mobile ${open ? "open" : ""}`} role="navigation" aria-label={`Menù mobile ${ruolo || "utente"}`}>
        <nav className="sidebar-mobile-nav">
          {menu.map(({ label, path, icon }) => (
            <NavLink
              key={path}
              to={path}
              className={({ isActive }) => `sidebar-mobile-link${isActive ? " active" : ""}`}
              onClick={() => setOpen(false)}
              end
            >
              {icon}
              {label}
            </NavLink>
          ))}
          <button
            onClick={handleLogout}
            className="sidebar-mobile-link btn btn-outline-danger mt-3"
          >
            <FaSignOutAlt /> Esci
          </button>
        </nav>
      </div>
    </>
  );
};

export default SidebarMobile;