import React, { useState, useEffect } from "react";
import {
  getAuth,
  updateProfile,
  updatePassword,
  onAuthStateChanged,
} from "firebase/auth";
import { doc, getDoc, updateDoc } from "firebase/firestore";
import { db } from "../services/firebase";
import { toast } from "react-toastify";

function ProfiloUtente() {
  const auth = getAuth();
  const [user, setUser] = useState(null);
  const [displayName, setDisplayName] = useState("");
  const [photoURL, setPhotoURL] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, setUser);
    return () => unsubscribe();
  }, [auth]);

  useEffect(() => {
    const fetchProfiloFirestore = async () => {
      if (!user) return;

      try {
        const ref = doc(db, "UTENTI", user.uid);
        const snap = await getDoc(ref);

        if (snap.exists()) {
          const dati = snap.data();
          setDisplayName(dati.Nome || user.displayName || "");
          setPhotoURL(user.photoURL || dati.Foto || "");
        } else {
          setDisplayName(user.displayName || "");
          setPhotoURL(user.photoURL || "");
        }
      } catch (error) {
        console.error("Errore nel recupero profilo:", error);
        toast.error("❌ Impossibile caricare il profilo");
      }
    };

    fetchProfiloFirestore();
  }, [user]);

  const handleUpdateProfile = async () => {
    if (!user) return;

    const nome = displayName.trim();
    const foto = photoURL.trim();

    if (!nome && !foto) {
      toast.error("⚠️ Inserisci almeno un campo da aggiornare");
      return;
    }

    setLoading(true);
    try {
      await updateProfile(user, {
        displayName: nome,
        photoURL: foto,
      });

      const ref = doc(db, "UTENTI", user.uid);
      await updateDoc(ref, {
        Nome: nome,
        Foto: foto,
      });

      toast.success("✅ Profilo aggiornato con successo");
    } catch (error) {
      console.error("Errore nell'aggiornamento profilo:", error);
      toast.error("❌ Errore nell'aggiornamento");
    } finally {
      setLoading(false);
    }
  };

  const handleChangePassword = async () => {
    if (!user || !newPassword.trim()) {
      toast.error("⚠️ Inserisci una nuova password");
      return;
    }

    if (newPassword.length < 6) {
      toast.error("🔐 La password deve avere almeno 6 caratteri");
      return;
    }

    setLoading(true);
    try {
      await updatePassword(user, newPassword);
      toast.success("🔑 Password aggiornata");
      setNewPassword("");
    } catch (error) {
      if (error.code === "auth/requires-recent-login") {
        toast.error(
          "⚠️ Per motivi di sicurezza, effettua nuovamente il login per cambiare la password."
        );
      } else {
        console.error("Errore cambio password:", error);
        toast.error("❌ Errore nel cambio password");
      }
    } finally {
      setLoading(false);
    }
  };

  if (!user) {
    return <p className="text-muted">🔒 Nessun utente autenticato.</p>;
  }

  return (
    <div className="card p-3 mb-4" role="region" aria-label="Profilo utente">
      <h5>👤 Profilo Utente</h5>

      <div className="mb-2">
        <label htmlFor="displayName">Nome visualizzato</label>
        <input
          id="displayName"
          type="text"
          className="form-control"
          value={displayName}
          onChange={(e) => setDisplayName(e.target.value)}
        />
      </div>

      <div className="mb-2">
        <label htmlFor="photoURL">URL foto profilo</label>
        <input
          id="photoURL"
          type="text"
          className="form-control"
          value={photoURL}
          onChange={(e) => setPhotoURL(e.target.value)}
        />
      </div>

      {photoURL && (
        <div className="mt-3">
          <p className="mb-1">
            <strong>Anteprima foto:</strong>
          </p>
          <img
            src={photoURL}
            alt="Foto profilo"
            className="img-thumbnail"
            style={{ maxWidth: "150px" }}
          />
        </div>
      )}

      <div className="mt-3">
        <strong>Email:</strong> {user.email || "—"}
      </div>
      <div className="mb-2">
        <strong>UID:</strong> {user.uid}
      </div>

      <button
        className="btn btn-primary mt-3"
        onClick={handleUpdateProfile}
        disabled={loading}
      >
        {loading ? "⏳ Aggiornamento..." : "💾 Salva modifiche"}
      </button>

      <hr className="my-4" />

      <h6>🔐 Cambia Password</h6>
      <div className="mb-2">
        <input
          type="password"
          className="form-control"
          placeholder="Nuova password"
          value={newPassword}
          onChange={(e) => setNewPassword(e.target.value)}
        />
      </div>
      <button
        className="btn btn-warning"
        onClick={handleChangePassword}
        disabled={loading}
      >
        {loading ? "⏳ In corso..." : "🔄 Aggiorna password"}
      </button>
    </div>
  );
}

export default ProfiloUtente;