import React, { useEffect, useState } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../services/firebase";
import "./dashboard.css";

const StoricoInterventi = () => {
  const [interventi, setInterventi] = useState([]);

  useEffect(() => {
    const fetchInterventi = async () => {
      try {
        const snapshot = await getDocs(collection(db, "INTERVENTI"));
        const lista = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        setInterventi(lista);
        console.log("📄 Interventi caricati:", lista.length);
      } catch (error) {
        console.error("❌ Errore nel caricamento interventi:", error.message);
      }
    };

    fetchInterventi();
  }, []);

  return (
    <div className="card">
      <div className="card-header bg-primary text-white">
        📄 Storico Interventi
      </div>
      <div className="card-body">
        {interventi.length === 0 ? (
          <p>Nessun intervento registrato.</p>
        ) : (
          <table className="table">
            <thead>
              <tr>
                <th>Cliente</th>
                <th>Mezzo</th>
                <th>Tipo</th>
                <th>Data</th>
                <th>Descrizione</th>
              </tr>
            </thead>
            <tbody>
              {interventi.map(i => (
                <tr key={i.id}>
                  <td>{i.cliente || "—"}</td>
                  <td>{i.mezzo || "—"}</td>
                  <td>{i.tipoIntervento || "—"}</td>
                  <td>{i.data || "—"}</td>
                  <td>{i.descrizione || "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default StoricoInterventi;