import React, { useState, useEffect } from "react";
import 'bootstrap/dist/css/bootstrap.min.css';
import { Routes, Route, useNavigate, Navigate } from "react-router-dom";
import { onAuthStateChanged } from "firebase/auth";
import { doc, getDoc } from "firebase/firestore";
import { db, auth } from "./services/firebase";

import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

import Sidebar from "./components/Sidebar";
import SidebarMobile from "./components/SidebarMobile";
import ProtectedRoute from "./components/ProtectedRoute";

// Pagine principali
import Login from "./pages/Login";
import DashboardAdmin from "./pages/DashboardAdmin";
import DashboardTecnico from "./pages/DashboardTecnico";
import ProfiloUtente from "./pages/ProfiloUtente";
import CalendarioManutenzioni from "./pages/CalendarioManutenzioni";
import CambioPassword from "./pages/CambioPassword";
import StoricoInterventi from "./pages/StoricoInterventi";
import Home from "./pages/Home";

// Pagine aggiuntive
import Clienti from "./pages/Clienti";
import Mezzi from "./pages/Mezzi";
import ReportInterventi from "./pages/ReportInterventi";
import Utenti from "./pages/Utenti";
import MappaClienti from "./pages/MappaClienti";
import NuovoIntervento from "./pages/NuovoIntervento";
import GestioneUtenti from "./pages/GestioneUtenti";

import { AuthContext } from "./contexts/AuthContext";
import "./App.css";

function App() {
  const [utente, setUtente] = useState(null);
  const [ruoloUtente, setRuoloUtente] = useState("");
  const [loadingRuolo, setLoadingRuolo] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      console.log("👤 Utente autenticato:", user);
      setUtente(user);

      if (user) {
        try {
          const ref = doc(db, "UTENTI", user.uid);
          const snapshot = await getDoc(ref);

          if (!snapshot.exists()) {
            toast.error("Utente non trovato nel database.");
            setRuoloUtente("ospite");
            setLoadingRuolo(false);
            return;
          }

          const dati = snapshot.data();
          const ruolo = (dati.ruolo || dati.Ruolo || dati.Role || "").trim().toLowerCase();

          if (!ruolo) {
            toast.error("Ruolo non definito per l'utente.");
            setRuoloUtente("ospite");
            setLoadingRuolo(false);
            return;
          }

          console.log("🎯 Ruolo trovato:", ruolo);
          setRuoloUtente(ruolo);
        } catch (error) {
          console.error("❌ Errore Firestore:", error.message);
          toast.error("Errore nel recupero del ruolo utente.");
          setRuoloUtente("errore");
        } finally {
          setLoadingRuolo(false);
        }
      } else {
        setRuoloUtente("");
        setLoadingRuolo(false);
      }
    });

    return () => unsubscribe();
  }, []);

  if (!utente) return <Login />;
  if (loadingRuolo) return <p className="text-muted p-3">🔄 Caricamento ruolo utente...</p>;

  return (
    <AuthContext.Provider value={{ user: utente, ruolo: ruoloUtente }}>
      <div className="app-layout">
        {/* Sidebar desktop */}
        <aside className="sidebar d-none d-md-flex">
          <Sidebar ruolo={ruoloUtente} />
        </aside>

        {/* Sidebar mobile */}
        <aside className="sidebar-mobile d-md-none">
          <SidebarMobile ruolo={ruoloUtente} />
        </aside>

        {/* Contenuto principale */}
        <main className="main-content">
          <ToastContainer position="top-right" autoClose={3000} />
          <Routes>
            {/* Login */}
            <Route path="/login" element={<Login />} />

            {/* Dashboard */}
            <Route
              path="/"
              element={
                ruoloUtente === "admin" ? <DashboardAdmin /> :
                ruoloUtente === "tecnico" ? <DashboardTecnico /> :
                <Navigate to="/login" />
              }
            />

            {/* Pagine generiche */}
            <Route
              path="/home"
              element={
                <ProtectedRoute>
                  <Home />
                </ProtectedRoute>
              }
            />
            <Route
              path="/profilo"
              element={
                <ProtectedRoute>
                  <ProfiloUtente />
                </ProtectedRoute>
              }
            />
            <Route
              path="/recupero"
              element={
                <ProtectedRoute>
                  <CambioPassword />
                </ProtectedRoute>
              }
            />
            <Route
              path="/storico-interventi"
              element={
                <ProtectedRoute>
                  <StoricoInterventi />
                </ProtectedRoute>
              }
            />
            <Route
              path="/calendario"
              element={
                <ProtectedRoute>
                  <CalendarioManutenzioni />
                </ProtectedRoute>
              }
            />
            <Route
              path="/manutenzioni-programmate/calendario"
              element={
                <ProtectedRoute>
                  <CalendarioManutenzioni />
                </ProtectedRoute>
              }
            />

            {/* Pagine funzionali */}
            <Route
              path="/nuovo-intervento"
              element={
                <ProtectedRoute>
                  <NuovoIntervento />
                </ProtectedRoute>
              }
            />
            <Route
              path="/report"
              element={
                <ProtectedRoute>
                  <ReportInterventi />
                </ProtectedRoute>
              }
            />
            <Route
              path="/clienti"
              element={
                <ProtectedRoute>
                  <Clienti />
                </ProtectedRoute>
              }
            />
            <Route
              path="/mezzi"
              element={
                <ProtectedRoute>
                  <Mezzi />
                </ProtectedRoute>
              }
            />
            <Route
              path="/mappa-clienti"
              element={
                <ProtectedRoute>
                  <MappaClienti />
                </ProtectedRoute>
              }
            />

            {/* Pagine protette (solo admin) */}
            <Route
              path="/utenti"
              element={
                <ProtectedRoute ruoloRichiesto="admin">
                  <Utenti />
                </ProtectedRoute>
              }
            />
            <Route
              path="/gestione-utenti"
              element={
                <ProtectedRoute ruoloRichiesto="admin">
                  <GestioneUtenti />
                </ProtectedRoute>
              }
            />
          </Routes>
        </main>
      </div>
    </AuthContext.Provider>
  );
}

export default App;