import React, { useState } from "react";
import { createUserWithEmailAndPassword } from "firebase/auth";
import { collection, addDoc } from "firebase/firestore";
import { auth, db } from "../services/firebase";
import "./dashboard.css";
import { toast } from "react-toastify";

const CreaUtente = () => {
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [conferma, setConferma] = useState("");
  const [ruolo, setRuolo] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!nome || !email || !password || password !== conferma || !ruolo) {
      toast.error("⚠️ Compila tutti i campi correttamente");
      return;
    }

    try {
      // 1️⃣ Crea utente su Firebase Authentication
      const credenziali = await createUserWithEmailAndPassword(auth, email, password);
      const uid = credenziali.user.uid;

      // 2️⃣ Salva i dati su Firestore
      await addDoc(collection(db, "UTENTI"), {
        nome,
        email,
        uid,
        ruolo: ruolo.toLowerCase()
      });

      toast.success("✅ Utente creato con successo");
      setNome("");
      setEmail("");
      setPassword("");
      setConferma("");
      setRuolo("");
    } catch (error) {
      console.error("❌ Errore nella creazione:", error.message);
      toast.error("Errore: " + error.message);
    }
  };

  return (
    <form className="form-grid" onSubmit={handleSubmit}>
      <h5 className="mb-3">➕ Crea Nuovo Utente</h5>

      <div>
        <label>Nome completo</label>
        <input
          type="text"
          value={nome}
          onChange={(e) => setNome(e.target.value)}
          placeholder="Mario Rossi"
        />
      </div>

      <div>
        <label>Email</label>
        <input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="mario.rossi@example.com"
        />
      </div>

      <div>
        <label>Password</label>
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          placeholder="Minimo 6 caratteri"
        />
      </div>

      <div>
        <label>Conferma Password</label>
        <input
          type="password"
          value={conferma}
          onChange={(e) => setConferma(e.target.value)}
        />
      </div>

      <div>
        <label>Ruolo</label>
        <select value={ruolo} onChange={(e) => setRuolo(e.target.value)}>
          <option value="">Seleziona ruolo...</option>
          <option value="admin">Admin</option>
          <option value="tecnico">Tecnico</option>
          <option value="cliente">Cliente</option>
        </select>
      </div>

      <div style={{ gridColumn: "span 2", textAlign: "right" }}>
        <button type="submit" className="btn-success">➕ Crea Utente</button>
      </div>
    </form>
  );
};

export default CreaUtente;