import React from "react";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import PropTypes from "prop-types";

/**
 * Visualizza una mappa con marker per il cliente.
 * @param {Object} props
 * @param {{ lat: number, lng: number }} props.coordinate - Coordinate geografiche
 * @param {string} props.nome - Nome del cliente da mostrare nel popup
 */
const MappaClienti = ({ coordinate, nome = "Cliente" }) => {
  const isValid =
    coordinate &&
    typeof coordinate.lat === "number" &&
    typeof coordinate.lng === "number";

  if (!isValid) {
    return (
      <div className="mt-4 text-muted">
        <h5>Mappa Cliente</h5>
        <p>⚠️ Coordinate non disponibili o non valide.</p>
      </div>
    );
  }

  return (
    <div className="mt-4">
      <h5>Mappa Cliente</h5>
      <MapContainer
        center={[coordinate.lat, coordinate.lng]}
        zoom={13}
        style={{ height: "400px", width: "100%" }}
        scrollWheelZoom={false}
      >
        <TileLayer
          attribution='© <a href="https://www.openstreetmap.org/">OpenStreetMap</a>'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        <Marker position={[coordinate.lat, coordinate.lng]}>
          <Popup>{nome}</Popup>
        </Marker>
      </MapContainer>
    </div>
  );
};

MappaClienti.propTypes = {
  coordinate: PropTypes.shape({
    lat: PropTypes.number.isRequired,
    lng: PropTypes.number.isRequired
  }),
  nome: PropTypes.string
};

export default MappaClienti;