import React, { useEffect, useState } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../services/firebase";
import "../styles/dashboard.css";

const Clienti = () => {
  const [clienti, setClienti] = useState([]);

  useEffect(() => {
    const fetchClienti = async () => {
      try {
        const snapshot = await getDocs(collection(db, "CLIENTI"));
        const lista = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        setClienti(lista);
        console.log("✅ Clienti caricati:", lista.length);
      } catch (error) {
        console.error("❌ Errore nel caricamento clienti:", error.message);
      }
    };

    fetchClienti();
  }, []);

  return (
    <div className="card">
      <div className="card-header">📁 Elenco Clienti</div>
      <div className="card-body">
        {clienti.length === 0 ? (
          <p>Nessun cliente trovato.</p>
        ) : (
          <table className="table">
            <thead>
              <tr>
                <th>Ragione Sociale</th>
                <th>Comune</th>
                <th>Provincia</th>
                <th>Codice Interno</th>
              </tr>
            </thead>
            <tbody>
              {clienti.map(c => (
                <tr key={c.id}>
                  <td>{c.ragioneSociale || "—"}</td>
                  <td>{c.comune || "—"}</td>
                  <td>{c.provincia || "—"}</td>
                  <td>{c.codiceInterno || "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default Clienti;