import React, { useEffect, useState } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../services/firebase";
import "../styles/dashboard.css";

const Mezzi = () => {
  const [mezzi, setMezzi] = useState([]);

  useEffect(() => {
    const fetchMezzi = async () => {
      try {
        const snapshot = await getDocs(collection(db, "MEZZI"));
        const lista = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        setMezzi(lista);
        console.log("🚗 Mezzi caricati:", lista.length);
      } catch (error) {
        console.error("❌ Errore nel caricamento mezzi:", error.message);
      }
    };

    fetchMezzi();
  }, []);

  return (
    <div className="card">
      <div className="card-header">🚗 Elenco Mezzi</div>
      <div className="card-body">
        {mezzi.length === 0 ? (
          <p>Nessun mezzo disponibile.</p>
        ) : (
          <table className="table">
            <thead>
              <tr>
                <th>Matricola</th>
                <th>Tipo</th>
                <th>Cliente</th>
                <th>Ultima Manutenzione</th>
              </tr>
            </thead>
            <tbody>
              {mezzi.map(m => (
                <tr key={m.id}>
                  <td>{m.matricola || "—"}</td>
                  <td>{m.tipo || "—"}</td>
                  <td>{m.cliente || "—"}</td>
                  <td>
                    {m.dataUltimaManutenzione?.seconds
                      ? new Date(m.dataUltimaManutenzione.seconds * 1000).toLocaleDateString("it-IT")
                      : "—"}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default Mezzi;