import React from "react";
import "./PaginaLayout.css";

const PaginaLayout = ({ titolo, children }) => {
  return (
    <div className="pagina-container">
      <h2 className="pagina-titolo">{titolo}</h2>
      <div className="pagina-box">
        {children}
      </div>
    </div>
  );
};

export default PaginaLayout;