import React, { useEffect, useState } from "react";
import { collection, getDocs, doc, updateDoc } from "firebase/firestore";
import { db } from "../services/firebase";
import "../styles/dashboard.css";

const Utenti = () => {
  const [utenti, setUtenti] = useState([]);
  const [editingId, setEditingId] = useState(null);
  const [formData, setFormData] = useState({ nome: "", email: "", ruolo: "" });

  useEffect(() => {
    const fetchUtenti = async () => {
      try {
        const snapshot = await getDocs(collection(db, "UTENTI"));
        const lista = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        setUtenti(lista);
      } catch (error) {
        console.error("Errore nel caricamento utenti:", error.message);
      }
    };
    fetchUtenti();
  }, []);

  const startEdit = (utente) => {
    setEditingId(utente.id);
    setFormData({
      nome: utente.nome || "",
      email: utente.email || "",
      ruolo: utente.ruolo || ""
    });
  };

  const cancelEdit = () => {
    setEditingId(null);
    setFormData({ nome: "", email: "", ruolo: "" });
  };

  const saveEdit = async () => {
    try {
      const ref = doc(db, "UTENTI", editingId);
      await updateDoc(ref, formData);
      setUtenti(prev =>
        prev.map(u => (u.id === editingId ? { ...u, ...formData } : u))
      );
      cancelEdit();
    } catch (error) {
      console.error("Errore nel salvataggio:", error.message);
    }
  };

  return (
    <div className="card">
      <div className="card-header">👥 Gestione Utenti</div>
      <div className="card-body">
        <table className="table">
          <thead>
            <tr>
              <th>Nome</th>
              <th>Email</th>
              <th>Ruolo</th>
              <th>Azioni</th>
            </tr>
          </thead>
          <tbody>
            {utenti.map(u => (
              <tr key={u.id}>
                <td>
                  {editingId === u.id ? (
                    <input
                      type="text"
                      value={formData.nome}
                      onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
                    />
                  ) : (
                    u.nome || "—"
                  )}
                </td>
                <td>
                  {editingId === u.id ? (
                    <input
                      type="email"
                      value={formData.email}
                      onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                    />
                  ) : (
                    u.email || "—"
                  )}
                </td>
                <td>
                  {editingId === u.id ? (
                    <select
                      value={formData.ruolo}
                      onChange={(e) => setFormData({ ...formData, ruolo: e.target.value })}
                    >
                      <option value="">—</option>
                      <option value="admin">Admin</option>
                      <option value="tecnico">Tecnico</option>
                      <option value="cliente">Cliente</option>
                    </select>
                  ) : (
                    u.ruolo || "—"
                  )}
                </td>
                <td>
                  {editingId === u.id ? (
                    <>
                      <button className="btn-success" onClick={saveEdit}>💾 Salva</button>{" "}
                      <button className="btn-warning" onClick={cancelEdit}>↩️ Annulla</button>
                    </>
                  ) : (
                    <button className="btn-warning" onClick={() => startEdit(u)}>✏️ Modifica</button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Utenti;