import React from "react";
import { useNavigate } from "react-router-dom";
import "./dashboard.css";

const Home = () => {
  const navigate = useNavigate();

  const sezioni = [
    {
      titolo: "🛠️ Nuovo Intervento",
      descrizione: "Registra un nuovo intervento tecnico per un cliente.",
      link: "/dashboard-admin",
      colore: "#0d6efd",
    },
    {
      titolo: "📋 Elenco Utenti",
      descrizione: "Gestisci gli utenti registrati e i loro ruoli.",
      link: "/dashboard-admin",
      colore: "#198754",
    },
    {
      titolo: "📅 Calendario Manutenzioni",
      descrizione: "Visualizza le manutenzioni programmate e le prossime scadenze.",
      link: "/calendario",
      colore: "#ffc107",
    },
    {
      titolo: "🔐 Cambio Password",
      descrizione: "Aggiorna la tua password in modo sicuro.",
      link: "/cambio-password",
      colore: "#dc3545",
    },
    {
      titolo: "📄 Storico Interventi",
      descrizione: "Consulta tutti gli interventi effettuati.",
      link: "/storico-interventi",
      colore: "#6f42c1",
    },
  ];

  return (
    <div className="card">
      <div className="card-header bg-primary text-white">
        👋 Benvenuto Massimo
      </div>
      <div className="card-body">
        <p style={{ fontSize: "1.1rem", marginBottom: "1.5rem" }}>
          Seleziona una sezione per iniziare. Tutto è a portata di clic.
        </p>
        <div className="form-grid">
          {sezioni.map((s, index) => (
            <div
              key={index}
              style={{
                border: `2px solid ${s.colore}`,
                borderRadius: "8px",
                padding: "1rem",
                backgroundColor: "#fff",
                boxShadow: "0 0 10px rgba(0,0,0,0.05)",
                cursor: "pointer",
              }}
              onClick={() => navigate(s.link)}
            >
              <h5 style={{ color: s.colore }}>{s.titolo}</h5>
              <p style={{ marginBottom: 0 }}>{s.descrizione}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Home;